import numpy as np

K10 = np.array([[-1, 1.5], [1, 1], [-0.5, 0.5], [1.5, 0.5], [-1.5, 0], [0.5, 0], [-1, -0.5], [0, -1], [1.5, -1], [0.5, -1.5]], dtype=float)
V10 = np.array([-0.8, -0.5, 0.2, 0.6, 0.1, 0.4, 0.9, -0.3, -1.1, 1.2])


def soft(q, K, V, tau):
    s = -((K - np.asarray(q, dtype=float)) ** 2).sum(axis=1) / tau
    a = np.exp(s - s.max())
    return float(a @ V / a.sum())


def fd(q, K, V, tau, eps=1e-6):
    q = np.asarray(q, dtype=float)
    out = []
    for j in range(len(q)):
        u, d = q.copy(), q.copy()
        u[j] += eps
        d[j] -= eps
        out.append((soft(u, K, V, tau) - soft(d, K, V, tau)) / (2 * eps))
    return np.array(out)
